from __future__ import annotations

import sqlite3

__all__ = ["TodoRepo"]


class TodoRepo:
    def __init__(self, path: str = ":memory:") -> None:
        self._conn: sqlite3.Connection | None = sqlite3.connect(path)
        self._conn.execute(
            """
            CREATE TABLE IF NOT EXISTS todos (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                priority INTEGER NOT NULL CHECK (priority BETWEEN 1 AND 5),
                done INTEGER NOT NULL DEFAULT 0
            )
            """
        )
        self._conn.commit()

    def add(self, title: str, priority: int = 3) -> int:
        if not isinstance(title, str):
            raise ValueError("title must be a string")

        stripped_title = title.strip()
        if not stripped_title:
            raise ValueError("title must not be empty")

        if isinstance(priority, bool) or not isinstance(priority, int):
            raise ValueError("priority must be an integer")
        if not 1 <= priority <= 5:
            raise ValueError("priority must be between 1 and 5")

        cursor = self._conn.execute(
            "INSERT INTO todos (title, priority, done) VALUES (?, ?, 0)",
            (stripped_title, priority),
        )
        self._conn.commit()
        return cursor.lastrowid

    def _row_to_dict(self, row: tuple[int, str, int, int]) -> dict:
        return {
            "id": row[0],
            "title": row[1],
            "priority": row[2],
            "done": bool(row[3]),
        }

    def get(self, todo_id: int) -> dict | None:
        cursor = self._conn.execute(
            "SELECT id, title, priority, done FROM todos WHERE id = ?",
            (todo_id,),
        )
        row = cursor.fetchone()
        if row is None:
            return None
        return self._row_to_dict(row)

    def list(self, done: bool | None = None) -> list[dict]:
        if done is None:
            cursor = self._conn.execute(
                "SELECT id, title, priority, done FROM todos "
                "ORDER BY priority ASC, id ASC"
            )
        else:
            cursor = self._conn.execute(
                "SELECT id, title, priority, done FROM todos "
                "WHERE done = ? ORDER BY priority ASC, id ASC",
                (1 if done else 0,),
            )
        return [self._row_to_dict(row) for row in cursor.fetchall()]

    def mark_done(self, todo_id: int) -> bool:
        cursor = self._conn.execute(
            "SELECT 1 FROM todos WHERE id = ?",
            (todo_id,),
        )
        if cursor.fetchone() is None:
            return False

        self._conn.execute(
            "UPDATE todos SET done = 1 WHERE id = ?",
            (todo_id,),
        )
        self._conn.commit()
        return True

    def delete(self, todo_id: int) -> bool:
        cursor = self._conn.execute(
            "DELETE FROM todos WHERE id = ?",
            (todo_id,),
        )
        self._conn.commit()
        return cursor.rowcount > 0

    def count(self, done: bool | None = None) -> int:
        if done is None:
            cursor = self._conn.execute("SELECT COUNT(*) FROM todos")
        else:
            cursor = self._conn.execute(
                "SELECT COUNT(*) FROM todos WHERE done = ?",
                (1 if done else 0,),
            )
        return int(cursor.fetchone()[0])

    def close(self) -> None:
        if self._conn is None:
            return
        try:
            self._conn.commit()
        except sqlite3.ProgrammingError:
            pass
        self._conn.close()
        self._conn = None
